// ============================================================================
// ARM_Q_Channel_Low_Power_Interface_apb: APB4 register wrapper around ARM_Q_Channel_Low_Power_Interface_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/ARM_Q_Channel_Low_Power_Interface.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/ARM_Q_Channel_Low_Power_Interface.md
// ============================================================================
module ARM_Q_Channel_Low_Power_Interface_apb #(
  parameter int DW = 32,
  parameter int AW = 32,
  parameter int ACT_CYCLES = 16
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic qreqn,
  output logic qacceptn,
  output logic qdeny,
  output logic qactive
);
  localparam logic [31:0] ID_VALUE = 32'h51430200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [6:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd7) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_qacceptn;
  logic          c_qdeny;
  logic          c_qactive;
  logic          c_dev_event;
  logic          c_irq;
  ARM_Q_Channel_Low_Power_Interface_top #(.DW(DW), .AW(AW), .ACT_CYCLES(ACT_CYCLES)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .qreqn(qreqn),
    .qacceptn(c_qacceptn),
    .qdeny(c_qdeny),
    .qactive(c_qactive),
    .dev_event(c_dev_event),
    .irq(c_irq)
  );
  assign qacceptn = c_qacceptn;  // also readable in the registers
  assign qdeny = c_qdeny;  // also readable in the registers
  assign qactive = c_qactive;  // also readable in the registers

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [0:0] p_EVENT;   // 12'h014 EVENT (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      p_EVENT <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      p_EVENT <= (wr && hit[5]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_dev_event = p_EVENT;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
    irq_set[1] = c_qdeny;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd6: apb_rdata = 32'({c_qactive, c_qdeny, c_qacceptn});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
